public record Contract(Customer customer, Supplier supplier, LocalDate start) {
    public Contract {                                    // compact ctor: every path
        customer = Objects.requireNonNull(customer, "customer");
        supplier  = Objects.requireNonNull(supplier, "supplier");
        if (start.isBefore(LocalDate.now()))
            throw new IllegalArgumentException("start in the past");
    }
    public static Contract create(Customer c, Supplier s, LocalDate d) {
        return new Contract(c, s, d);   // named Essence-style entry point
    }
}

